function btLay(t,n){const CW=30,G=14,P=[];const wd=x=>{const cs=x.c.map(wd);x._cw=cs;x._w=Math.max(x.k.length*CW+10,cs.reduce((a,b)=>a+b,0)+G*Math.max(0,cs.length-1));return x._w};
const pl=(x,l,d,par)=>{const id=P.length,pg={keys:x.k,w:x.k.length*CW+10,y:26+d*62,par,d,bad:x.k.length>2*n||(par>=0&&x.k.length<n)};P.push(pg);let cx;if(!x.c.length)cx=l+x._w/2;else{const sum=x._cw.reduce((a,b)=>a+b,0)+G*(x.c.length-1);let cur=l+(x._w-sum)/2;const ids=[];x.c.forEach((c,i)=>{ids.push(pl(c,cur,d+1,id));cur+=x._cw[i]+G});cx=(P[ids[0]].x0+P[ids[ids.length-1]].x0)/2}pg.x0=cx;return id};
const W=wd(t);pl(t,10,0,-1);let dm=0;P.forEach(p=>{const o=BOFF[p.keys[0]]||[0,0];p.x=p.x0+o[0];p.y+=o[1];dm=Math.max(dm,p.d)});return{P,W:W+20,H:dm*62+66}}
function btSvg(P,W,H,hi,n){let s='';P.forEach(p=>{if(p.par>=0&&P[p.par])s+=`<line class="e" x1="${P[p.par].x}" y1="${P[p.par].y+28}" x2="${p.x}" y2="${p.y}" opacity="${Math.min(p.o??1,P[p.par].o??1)}"/>`});
P.forEach(p=>{const x0=p.x-p.w/2,CW=30;s+=`<g class="pg" data-k="${p.keys[0]}" style="cursor:grab" opacity="${p.o??1}"><rect x="${x0}" y="${p.y}" width="${p.w}" height="28" rx="5" fill="var(--card,#fff)" stroke="${p.bad?'#e5484d':'currentColor'}" stroke-width="${p.bad?3:1.2}"/>`+p.keys.map((v,i)=>`<rect x="${x0+5+i*CW}" y="${p.y+3}" width="${CW-2}" height="22" rx="4" fill="${hi.includes(v)?'#f2a93b':'none'}" opacity="${hi.includes(v)?.55:1}"/><text x="${x0+5+i*CW+(CW-2)/2}" y="${p.y+14}">${v}</text>`).join('')+'</g>'});
return`<div class="scroll"><svg viewBox="0 0 ${W} ${H}" style="min-width:${W}px;overflow:visible">${s}</svg></div><p style="font-size:12px;margin:4px 0">Each box is a <b>page</b> (a node with several keys). <b style="color:#e5484d">Red outline</b> = too many or too few keys. <b style="color:#f2a93b">Orange</b> = the key being worked on. Drag a box to move it.</p>`}
function btDraw(t,n,hi){if(!t||!t.k.length)return'<p><i>(empty tree)</i></p>';const L=btLay(t,n);return btSvg(L.P,L.W,L.H,hi||[],n)}
function btTween(box,f,t,hi,n){if(!f||!t||!f.k.length||!t.k.length||typeof requestAnimationFrame=='undefined'){box.innerHTML=btDraw(t,n,hi);return}const A=btLay(f,n),B=btLay(t,n),W=Math.max(A.W,B.W),H=Math.max(A.H,B.H),t0=performance.now();cancelAnimationFrame(box._raf);
const pr=[];B.P.forEach((b,j)=>A.P.forEach((a,i)=>{const c=b.keys.filter(k=>a.keys.includes(k)).length;if(c)pr.push([c,i,j])}));pr.sort((a,b)=>b[0]-a[0]);const mt={},ua={};pr.forEach(([c,i,j])=>{if(!(j in mt)&&!ua[i]){mt[j]=i;ua[i]=1}});
const tk=now=>{const u=Math.min(1,(now-t0)/750),e=u<.5?2*u*u:1-Math.pow(-2*u+2,2)/2,M=B.P.map((b,j)=>{const a=j in mt?A.P[mt[j]]:null;return a?{...b,x:a.x+(b.x-a.x)*e,y:a.y+(b.y-a.y)*e,w:a.w+(b.w-a.w)*e,o:1}:{...b,o:e}});
A.P.forEach((a,i)=>{if(!ua[i]&&u<1)M.push({...a,par:-1,o:1-e})});box.innerHTML=btSvg(M,W,H,hi,n);if(u<1)box._raf=requestAnimationFrame(tk)};box._raf=requestAnimationFrame(tk)}
function btKeys(){const v=$('#bk').value.trim();return(v.match(/[ds]?\s*\d+/gi)||[]).map(x=>({k:+x.replace(/\D/g,''),d:/^d/i.test(x),s:/^s/i.test(x)})).slice(0,25)}
function btQ(){const n=+$('#bo').value,r=btRun(n,btKeys()),st=[];$('#sv').innerHTML='';if(!r.R.length)return{st:[],q:[]};
r.R.forEach(x=>{if(x.op=='s'){st.push({n:[],e:[],t:`Search <b>${x.k}</b>: start at the root; in each page find the first key ≥ ${x.k}; if it is equal, stop; otherwise go to the child just before it. ${x.f?'<b>Found.</b>':'<b>Not found</b> (we reached a leaf).'}`,h:btDraw(x.t2,n,x.vis)});return}
if(x.op=='i')st.push({n:[],e:[],t:`Add <b>${x.k}</b>: insertion always happens in a leaf, after an unsuccessful search.${x.ev.length?'':' The leaf has room (Case I), so the key is just placed in order.'}`,h:btDraw(x.t1,n,[x.k])});
else st.push({n:[],e:[],t:`Remove <b>${x.k}</b> (order B-${n}: every page except the root keeps between ${n} and ${2*n} keys).`,h:btDraw(x.t1,n,[x.k])});
if(x.ev.length)st.push({n:[],e:[],t:x.ev.join('<br>'),h:btDraw(x.t2,n,[x.k]),a:{f:x.t1,t:x.t2,hi:[x.k],n}})});
const t=r.root;return{st,q:[['Height of the final tree (number of levels)',btH(t)],['Number of pages in the final tree',btCnt(t)],['Number of keys in the root page',t.k.length],['How many page SPLITS happened in total?',r.sp],['How many MERGES happened in total?',r.mg],['How many times did a page BORROW a key from a neighbor?',r.br]]}}
function btLive(){let AH=[],lh=[],msg='Add, remove or search numbers. Boxes are pages; they split and merge by themselves, and you can drag them around.';const box=$('#sv'),res=()=>btRun(+$('#bo').value,AH);
const has=(t,k)=>t&&(t.k.includes(k)||(t.c.length&&has(t.c[t.k.findIndex(x=>x>k)<0?t.c.length-1:t.k.findIndex(x=>x>k)],k)));
const show=(hi,x)=>{lh=hi||[];const r=res(),n=r.n;box.innerHTML=`<p class="tip">${msg}</p><div id="lt"></div>`;const lt=$('#lt');if(x&&x.ev.length){lt.innerHTML=btDraw(x.t1,n,lh);setTimeout(()=>btTween(lt,x.t1,x.t2,lh,n),700)}else lt.innerHTML=btDraw(r.root,n,lh)};
const act=m=>{const k=parseInt($('#bv').value);if(isNaN(k)){msg='Type a number first.';return show()}const e=has(res().root,k);
if(m=='s'){const r=btRun(+$('#bo').value,[...AH,{k,s:1}]),x=r.R[r.R.length-1];msg=e?`Found ${k}.`:`${k} is not in the tree.`;return show(x.vis)}
let x=null;if(m=='i'&&e)msg=`${k} is already in the tree (no repeated numbers).`;else if(m=='d'&&!e)msg=`${k} is not in the tree.`;else{AH.push({k,d:m=='d'});const r=res();x=r.R[r.R.length-1];msg=`${m=='d'?'Removed':'Added'} <b>${k}</b>. ${x.ev.length?x.ev.join('<br>'):'No page had to change shape.'}`}show([k],x)};
$('#bi').onclick=()=>act('i');$('#bd').onclick=()=>act('d');$('#bs2').onclick=()=>act('s');$('#bc').onclick=()=>{AH=[];for(const q in BOFF)delete BOFF[q];msg='Empty tree.';show()};$('#bo').onchange=()=>{AH=[];msg='Order changed: tree cleared.';show()};
box.onpointerdown=e=>{const g=e.target.closest&&e.target.closest('.pg');if(!g)return;const v=g.dataset.k,s=g.ownerSVGElement,sc=s.viewBox.baseVal.width/s.getBoundingClientRect().width,x0=e.clientX,y0=e.clientY,b=BOFF[v]||[0,0];
const mv=ev=>{BOFF[v]=[b[0]+(ev.clientX-x0)*sc,b[1]+(ev.clientY-y0)*sc];show(lh)},up=()=>{removeEventListener('pointermove',mv);removeEventListener('pointerup',up)};addEventListener('pointermove',mv);addEventListener('pointerup',up);e.preventDefault()};show()}
const ORDER=Object.keys(PG);
const PGK='dsdProgress';let PRG={},flash='';try{PRG=JSON.parse(localStorage.getItem(PGK)||'{}')}catch(e){}
const savePrg=()=>{try{localStorage.setItem(PGK,JSON.stringify(PRG))}catch(e){}},mastered=id=>((PRG[id]||{}).best||0)>=100,started=id=>{const e=PRG[id];return !!(e&&(e.seen||e.tries))};
function rec(f){const id=cur;if(!id||!PG[id]||PG[id].game)return;const e=PRG[id]||(PRG[id]={seen:0,tries:0,best:0});if(f==='seen')e.seen=1;else{if(!(f>=0))return;const was=mastered(id);e.tries++;e.best=Math.max(e.best,Math.round(f*100));if(!was&&mastered(id))flash=' 🎉 Topic mastered!';const P=PG[id];if(LAUTO&&$('#rg')&&!P.doc&&!P.tree&&P.run&&gsig()==RS){if(f>=1&&LVL<8){LVL++;lvSave();lvInfo('🎉 Level up! The next random graph is level '+LVL);flash+=' ⬆ Level '+LVL}else if(f<.4&&LVL>1){LVL--;lvSave();lvInfo('Level lowered to '+LVL+' so you can practice at your pace');flash+=' ⬇ Level '+LVL}}if(TAUTO&&$('#br')&&P.tree&&RT&&tsig()==RT){if(f>=1&&TLVL<8){TLVL++;tlSave();tlInfo('🎉 Level up! The next random tree is level '+TLVL);flash+=' ⬆ Tree level '+TLVL}else if(f<.4&&TLVL>1){TLVL--;tlSave();tlInfo('Level lowered to '+TLVL+' so you can practice at your pace');flash+=' ⬇ Tree level '+TLVL}}if(id=='avlrot'&&AAUTO&&$('#al')&&RA&&$('#ak').value==RA){if(f>=1&&ALVL<8){ALVL++;alSave();alInfo('🎉 Level up! The next random list is level '+ALVL);flash+=' ⬆ AVL level '+ALVL}else if(f<.4&&ALVL>1){ALVL--;alSave();alInfo('Level lowered to '+ALVL+' so you can practice at your pace');flash+=' ⬇ AVL level '+ALVL}}if(id=='btree'&&BAUTO&&$('#bl')&&RB&&$('#bk').value==RB){if(f>=1&&BLVL<8){BLVL++;blSave();blInfo('🎉 Level up! The next random list is level '+BLVL);flash+=' ⬆ B-tree level '+BLVL}else if(f<.4&&BLVL>1){BLVL--;blSave();blInfo('Level lowered to '+BLVL+' so you can practice at your pace');flash+=' ⬇ B-tree level '+BLVL}}}savePrg();navR();pgBar()}
function navR(){$('#nav').innerHTML=ORDER.map(k=>`<button class="${k==cur?'on':''}" title="${(PRG[k]||{}).best?'Best practice score: '+PRG[k].best+'%':''}" onclick="go('${k}')">${PG[k].game?'':mastered(k)?'✅ ':started(k)?'🟡 ':''}${PG[k].t.split(' (')[0]}</button>`).join('')}
function pgBar(){const el=$('#pgbar');if(!el)return;const ids=ORDER.filter(k=>!PG[k].game),m=ids.filter(mastered).length,s=ids.filter(k=>started(k)&&!mastered(k)).length,pct=Math.round(m/ids.length*100);
el.innerHTML=`<div style="display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap;font-size:13px"><b>🏆 Your progress: ${m} / ${ids.length} topics mastered${s?` · ${s} in progress`:''}${flash}</b><span><small>✅ = 100% in a practice · 🟡 = started</small> <button id="pgr" style="padding:2px 8px;font-size:12px">Reset</button></span></div><div style="height:10px;border-radius:6px;background:#8884;margin-top:6px;overflow:hidden"><div style="height:100%;width:${pct}%;background:#16a34a;transition:width .4s"></div></div>`;flash='';
$('#pgr').onclick=()=>{if($('#pgr').dataset.s){PRG={};savePrg();navR();pgBar()}else{$('#pgr').dataset.s=1;$('#pgr').textContent='Sure? Click again'}}}

function go(id){cur=id;clearInterval(tm);const p=PG[id];hl={n:[],e:[]};
navR();if(!$('#pgbar'))$('#nav').insertAdjacentHTML('beforebegin','<div id="pgbar" class="card" style="max-width:956px;margin:10px auto"></div>');pgBar();
document.onkeydown=null;if(p.doc){$('#main').innerHTML=`<details class="card" open><summary>📖 Learn: ${p.t}</summary>${p.learn}</details><div class="card"><div class="bar">${p.ui}<button id="bs">▶ Show me step by step</button><button id="bq">✍ Solve it here</button></div><div id="sv"></div><div id="qz"></div><div id="out"></div></div><div class="card"><b>✍ Check yourself</b>${p.qs.map(([q,a])=>`<details><summary>${q}</summary><div class="tip">${a}</div></details>`).join('')}</div>`;
$('#bs').onclick=()=>{$('#qz').innerHTML='';steps(p.run())};$('#bq').onclick=()=>{$('#out').innerHTML='';quiz(p.run())};p.init&&p.init();return}if(p.game){$('#main').innerHTML='<div class="card" id="wd"></div>';return daily()}
$('#main').innerHTML=`<details class="card" open><summary>📖 Learn: ${p.t}</summary>${p.learn}<div class="bar"><button id="dm">🎬 Watch a demo on a tiny example</button></div></details><div class="card">${p.tree?treeUI():graphUI()}</div><div class="card"><div class="bar">${p.start?'<label>Start node # <input id="sn0" type="number" min="1" value="1"></label>':''}${p.avl?'<label>Numbers to add <input id="ak" style="width:210px" title="e.g. 10, 20, 30, d20 (d20 = remove 20)"></label>':''}${p.tree&&!p.avl?'':'<button id="bs">▶ Show me step by step</button>'}<button id="bq">✍ Solve it here</button>${p.avl?'<button id="bp">✍ Practice AVL insert</button>':''}</div><div id="qz"></div><div id="out"></div></div>`;
p.tree?initTree():initGraph();$('#dm').onclick=()=>demo(id);
const run=()=>{const s=p.start?Math.min(Math.max(+$('#sn0').value||1,1),G.nodes.length)-1:0;if(!p.tree&&!G.nodes.length)return null;return p.run(s)};
if($('#bs'))$('#bs').onclick=()=>{const R=run();$('#qz').innerHTML='';if(R)steps(R)};
if(id=='avl')avlInit();$('#bq').onclick=()=>{if(id=='avl')return avlQ();if(id=='trav')return travWalk();const R=run();$('#out').innerHTML='';hl={n:[],e:[]};if(!p.tree)draw();!R||!R.q.length?$('#qz').innerHTML='Add some nodes first!':R.st&&R.st.some(s=>s.f||s.m)?solve(R):quiz(R)}}
function steps(R){rec('seen');let i=0;$('#out').innerHTML=`<div class="bar"><button id="pv">◀ Prev</button><button id="nx">Next ▶</button><b id="sc0"></b></div><p id="stt" class="tip"></p><div class="scroll" id="sh"></div>`;
const u=()=>{const s=R.st[i];hl={n:s.n,e:s.e,d:s.d||[],c:s.c||{},v:s.v||{}};draw();$('#sc0').textContent=`Step ${i+1} / ${R.st.length}`;$('#stt').innerHTML=s.t;$('#sh').innerHTML=s.h;if(s.a)(s.a.n?btTween($('#sh'),s.a.f,s.a.t,s.a.hi,s.a.n):avlTween($('#sh'),s.a.f,s.a.t,s.a.hi))};
$('#pv').onclick=()=>{i=Math.max(0,i-1);u()};$('#nx').onclick=()=>{i=Math.min(R.st.length-1,i+1);u()};u()}
const norm=v=>{v=v.trim().toLowerCase().replace(/\s+/g,' ');return v=='inf'||v=='infinity'?'∞':v=='y'?'yes':v=='n'?'no':v};
function mquiz(R){let rd=0;$('#qz').innerHTML=`<p><b>Fill in Vector A</b> (the final Floyd result; diagonal is given). Use <code>inf</code> for ∞.</p><table class="m"><tr><th></th>${R.mat.map((_,j)=>`<th>${L(j)}</th>`).join('')}</tr>${R.mat.map((r,i)=>`<tr><th>${L(i)}</th>${r.map((x,j)=>i==j?'<td>0</td>':`<td><input data-i="${i}" data-j="${j}"></td>`).join('')}</tr>`).join('')}</table><div class="bar"><button id="ck">✔ Check</button><b id="sc"></b><button id="rv">Show me the steps</button></div>`;
$('#ck').onclick=()=>{let ok=0,t=0;document.querySelectorAll('table.m input').forEach(el=>{t++;const a=String(R.mat[el.dataset.i][el.dataset.j]),c=norm(el.value)==a;ok+=c;el.style.outline='3px solid '+(c?'#16a34a':'#dc2626');el.title=c?'':'answer: '+a;if(!c&&el.value)el.style.color='#b91c1c'});if(!rd){rd=1;rec(ok/t)}$('#sc').textContent=ok==t?'🎉 Perfect!':`${ok} / ${t} correct (red = wrong; hover for the answer, or press Show me the steps)`};$('#rv').onclick=()=>steps(R)}
function quiz(R){if(R.mat)return mquiz(R);$('#qz').innerHTML=`<p><b>Your turn!</b> Type your answers (use <code>inf</code> for ∞).</p>${R.title?'<b>'+R.title+'</b>':''}<div class="qs">${R.q.map(([l],i)=>`<label>${l}<input data-i="${i}"><small></small></label>`).join('')}</div><div class="bar"><button id="ck">✔ Check</button><b id="sc"></b><button id="rv" style="display:none">Show me the steps</button></div>`;
$('#ck').onclick=()=>{let ok=0;document.querySelectorAll('.qs input').forEach(el=>{const[,a,sq]=R.q[el.dataset.i],g=sq?(el.value.match(/\d+/g)||[]).join(' '):norm(el.value),c=g==String(a).toLowerCase();ok+=c;el.className=c?'ok':'bad';el.nextElementSibling.textContent=c?'✓':'✗ answer: '+a});
if(!R.rd){R.rd=1;rec(ok/R.q.length)}$('#sc').textContent=ok==R.q.length?'🎉 Perfect!':`${ok} / ${R.q.length} correct`;if(R.st){$('#rv').style.display='';$('#rv').onclick=()=>steps(R)}}}
go('basics');
